import os
from typing import Any, Dict, List, Optional

from azure.ai.documentintelligence import DocumentIntelligenceClient
from azure.core.credentials import AzureKeyCredential


def _get_field_confidence(field: Any) -> Optional[float]:
    if field is None:
        return None
    confidence = getattr(field, "confidence", None)
    if confidence is not None:
        try:
            return float(confidence)
        except (TypeError, ValueError):
            return None
    return None


def _get_field_value(field: Any) -> Any:
    if field is None:
        return None
    for attr in ("value", "content", "text"):
        value = getattr(field, attr, None)
        if value not in (None, ""):
            return value
    return None


def _parse_invoice_fields(result: Any) -> Dict[str, Any]:
    documents = getattr(result, "documents", None) or []
    if not documents:
        return {}

    doc = documents[0]
    fields = getattr(doc, "fields", None) or {}

    parsed = {}
    for name, field in fields.items():
        parsed[name] = {
            "value": _get_field_value(field),
            "confidence": _get_field_confidence(field),
        }
    return parsed


def extract_and_validate_invoice(
    document_bytes: bytes,
    required_fields: Optional[List[str]] = None,
    min_confidence: float = 0.8,
    model_id: str = "prebuilt-invoice",
) -> Dict[str, Any]:
    endpoint = os.environ["AZURE_DOCUMENT_INTELLIGENCE_ENDPOINT"]
    key = os.environ["AZURE_DOCUMENT_INTELLIGENCE_KEY"]

    if required_fields is None:
        required_fields = [
            "InvoiceId",
            "InvoiceDate",
            "VendorName",
            "CustomerName",
            "InvoiceTotal",
        ]

    client = DocumentIntelligenceClient(endpoint=endpoint, credential=AzureKeyCredential(key))

    poller = client.begin_analyze_document(
        model_id=model_id,
        analyze_request=document_bytes,
        content_type="application/pdf",
    )
    result = poller.result()

    extracted_fields = _parse_invoice_fields(result)

    missing_fields = []
    low_confidence_fields = []
    validated_fields = {}

    for field_name in required_fields:
        field_data = extracted_fields.get(field_name)
        if not field_data or field_data.get("value") in (None, ""):
            missing_fields.append(field_name)
            continue

        confidence = field_data.get("confidence")
        if confidence is None or confidence < min_confidence:
            low_confidence_fields.append(
                {
                    "field": field_name,
                    "confidence": confidence,
                    "threshold": min_confidence,
                }
            )

        validated_fields[field_name] = field_data

    return {
        "valid": not missing_fields and not low_confidence_fields,
        "required_fields": required_fields,
        "min_confidence": min_confidence,
        "missing_fields": missing_fields,
        "low_confidence_fields": low_confidence_fields,
        "fields": extracted_fields,
        "validated_fields": validated_fields,
        "model_id": model_id,
    }
